    pool=d.box('d1_pool',(.23,.123,.015),(-.22,y-.002,.027),water,bevel=.002)
    shaftwater=d.box('d1_shaftwater',(.040,.12,.08),(-.355,y,.06),water,bevel=.001)
    d.box('d1_gauge',(.006,.004,.24),(-.315,y-.067,.15),white,bevel=.001)
